def choose_move(observation):
    def clamp_step(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def pos(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return x[0], x[1]
        return None

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def step_away(a, b):
        return [clamp_step(a[0] - b[0]), clamp_step(a[1] - b[1])]

    env = observation.get("environment_name", "resource_collection")
    self_pos = pos(observation.get("self_position")) or (0, 0)
    opp_pos = pos(observation.get("opponent_position")) or self_pos
    w = observation.get("grid_width", 0) or 0
    h = observation.get("grid_height", 0) or 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)

        corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        corners = [c for c in corners if c[0] >= 0 and c[1] >= 0]
        if corners:
            target = max(corners, key=lambda c: dist(c, opp_pos))
            return step_toward(self_pos, target)
        return step_away(self_pos, opp_pos)

    if env == "territory_control":
        candidates = []
        for key in ("unclaimed_cells", "opponent_territory", "frontier_cells", "targets"):
            cells = observation.get(key) or []
            for cell in cells:
                p = pos(cell)
                if p is not None:
                    candidates.append(p)

        if candidates:
            target = min(candidates, key=lambda c: dist(c, self_pos))
            return step_toward(self_pos, target)

        center = ((w - 1) // 2 if w else self_pos[0], (h - 1) // 2 if h else self_pos[1])
        return step_toward(self_pos, center)

    resources = []
    for key in ("resources", "resource_positions", "resource_cells"):
        for item in observation.get(key) or []:
            p = pos(item)
            if p is not None:
                resources.append(p)

    if resources:
        target = min(resources, key=lambda c: dist(c, self_pos))
        if dist(opp_pos, target) <= dist(self_pos, target) and dist(self_pos, opp_pos) <= 2:
            away = step_away(self_pos, opp_pos)
            if away != [0, 0]:
                return away
        return step_toward(self_pos, target)

    if dist(self_pos, opp_pos) > 0:
        return step_away(self_pos, opp_pos)
    return [0, 0]

